'use client'

import Link from 'next/link'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { Badge } from '@/components/ui/badge'
import { cn } from '@/lib/utils'
import { formatCurrency } from '@/lib/utils'

export interface ArtistCardData {
  id: string
  display_name: string
  avatar_url: string | null
  calendar_color: string | null
  status: 'active' | 'on_leave' | 'archived'
  role?: string | null
  specialties: string[]
  booking_count_this_month: number
  commission_default_pct: number
  // Sprint 8 additions
  revenue_cents_this_month?: number | null
  first_photo_url?: string | null
}

interface ArtistCardProps {
  artist: ArtistCardData
}

const STATUS_CLASS: Record<string, string> = {
  active:    'badge-artist-active',
  on_leave:  'badge-artist-on-leave',
  archived:  'badge-artist-archived',
}

const STATUS_LABEL: Record<string, string> = {
  active:    'Active',
  on_leave:  'On Leave',
  archived:  'Archived',
}

const ROLE_CLASS: Record<string, string> = {
  owner:        'chip-role-owner',
  admin:        'chip-role-admin',
  artist:       'chip-role-artist',
  receptionist: 'chip-role-receptionist',
  guest_artist: 'chip-role-guest-artist',
}

const ROLE_LABEL: Record<string, string> = {
  owner:        'Owner',
  admin:        'Admin',
  artist:       'Artist',
  receptionist: 'Receptionist',
  guest_artist: 'Guest Artist',
}

function getInitials(name: string): string {
  return name
    .split(' ')
    .map((n) => n[0])
    .slice(0, 2)
    .join('')
    .toUpperCase()
}

interface StatCellProps {
  label: string
  value: string | number
}

function StatCell({ label, value }: StatCellProps) {
  return (
    <div className="flex flex-col items-center gap-0.5">
      <span className="text-[10px] text-muted-foreground leading-none">{label}</span>
      <span className="text-xs font-semibold tabular-nums leading-none">{value}</span>
    </div>
  )
}

export function ArtistCard({ artist }: ArtistCardProps) {
  const visibleSpecialties = artist.specialties.slice(0, 2)
  const extraCount = artist.specialties.length - 2

  return (
    <Link href={`/artists/${artist.id}`} className="block focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring rounded-xl">
      <div
        className={cn(
          'group relative cursor-pointer rounded-xl border border-border bg-card shadow-soft overflow-hidden',
          'kpi-card-hover hover:border-primary/30',
          'flex flex-col',
        )}
      >
        {/* Portfolio thumbnail strip */}
        <div className="relative h-28 rounded-t-xl overflow-hidden bg-muted">
          {artist.first_photo_url ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={artist.first_photo_url}
              alt=""
              className="h-full w-full object-cover"
              aria-hidden="true"
            />
          ) : (
            <div
              className="h-full w-full"
              style={
                artist.calendar_color
                  ? { background: `color-mix(in srgb, ${artist.calendar_color} 20%, transparent)` }
                  : undefined
              }
            />
          )}
        </div>

        {/* Body */}
        <div className="px-3 pb-3 flex flex-col gap-2 flex-1">
          {/* Avatar overlapping strip */}
          <div className="relative w-fit -mt-5 z-10">
            <Avatar className="h-10 w-10 rounded-full ring-2 ring-background">
              <AvatarImage src={artist.avatar_url ?? undefined} alt={artist.display_name} />
              <AvatarFallback className="bg-muted text-muted-foreground text-sm font-medium">
                {getInitials(artist.display_name)}
              </AvatarFallback>
            </Avatar>
            {artist.calendar_color && (
              <span
                className="cal-color-dot absolute -top-0.5 -right-0.5 ring-2 ring-background"
                style={{ backgroundColor: artist.calendar_color }}
                aria-hidden="true"
              />
            )}
          </div>

          {/* Name */}
          <p className="text-sm font-semibold leading-tight">{artist.display_name}</p>

          {/* Role + Status chips */}
          <div className="flex flex-wrap gap-1.5">
            {artist.role && ROLE_CLASS[artist.role] && (
              <span
                className={cn(
                  'inline-flex h-5 items-center rounded-full px-2 text-[10px] font-medium',
                  ROLE_CLASS[artist.role],
                )}
              >
                {ROLE_LABEL[artist.role] ?? artist.role}
              </span>
            )}
            <span
              className={cn(
                'inline-flex h-5 items-center rounded-full px-2 text-[10px] font-medium',
                STATUS_CLASS[artist.status] ?? 'badge-artist-archived',
              )}
            >
              {STATUS_LABEL[artist.status] ?? artist.status}
            </span>
          </div>

          {/* Specialties */}
          {artist.specialties.length > 0 && (
            <div className="flex flex-wrap gap-1">
              {visibleSpecialties.map((s) => (
                <Badge key={s} variant="outline" className="h-4 text-[10px] text-muted-foreground px-1.5">
                  {s}
                </Badge>
              ))}
              {extraCount > 0 && (
                <Badge variant="outline" className="h-4 text-[10px] text-muted-foreground px-1.5">
                  +{extraCount} more
                </Badge>
              )}
            </div>
          )}

          {/* 3-col stats row */}
          <div className="grid grid-cols-3 text-center border-t border-border/20 pt-2 mt-auto">
            <StatCell label="Appts/mo" value={artist.booking_count_this_month} />
            <StatCell
              label="Revenue"
              value={formatCurrency(artist.revenue_cents_this_month ?? 0)}
            />
            <StatCell label="Commission" value={`${artist.commission_default_pct}%`} />
          </div>

          {/* View profile link */}
          <p className="text-xs text-primary hover:underline text-right mt-0.5">
            View profile →
          </p>
        </div>
      </div>
    </Link>
  )
}

