interface ScheduleSlotRow {
  id: string
  start_time: string
  end_time: string
}

interface ScheduleCellProps {
  artistId: string
  artistName: string
  calendarColor: string | null
  date: Date
  slots: ScheduleSlotRow[]
  timeOff: TimeOff | null
  canEdit: boolean
  onAddSlot: (artistId: string, date: Date) => void
  onRemoveSlot: (slotId: string) => void
}

export function ScheduleCell({
  artistId,
  artistName,
  calendarColor,
  date,
  slots,
  timeOff,
  canEdit,
  onAddSlot,
  onRemoveSlot,
}: ScheduleCellProps) {
  const color = calendarColor ?? 'var(--primary)'
  const dayLabel = format(date, 'EEE d')

  if (timeOff) {
    return (
      <div className="relative min-h-[72px]">
        {/* Diagonal stripe overlay */}
        <div
          className="absolute inset-0 rounded pointer-events-none"
          style={{
            background: `repeating-linear-gradient(
              -45deg,
              transparent,
              transparent 4px,
              hsl(var(--muted)) 4px,
              hsl(var(--muted)) 5px
            )`,
            opacity: 0.4,
          }}
          aria-hidden="true"
        />
        <Tooltip>
          <TooltipTrigger asChild>
            <div className="relative z-10 flex items-center justify-center h-full min-h-[72px]">
              <span className="text-[10px] text-muted-foreground font-medium">
                {timeOff.reason ? (TIME_OFF_REASON_LABEL[timeOff.reason as keyof typeof TIME_OFF_REASON_LABEL] ?? 'Time off') : 'Time off'}
              </span>
            </div>
          </TooltipTrigger>
          <TooltipContent side="top">
            <p className="text-xs">{timeOff.reason ? (TIME_OFF_REASON_LABEL[timeOff.reason as keyof typeof TIME_OFF_REASON_LABEL] ?? 'Time off') : 'Time off'}</p>
            {timeOff.notes && <p className="text-xs text-muted-foreground mt-0.5">{timeOff.notes}</p>}
          </TooltipContent>
        </Tooltip>
      </div>
    )
  }

  if (slots.length > 0) {
    return (
      <div className="space-y-1 min-h-[72px]">
        {slots.map((slot) => (
          <div
            key={slot.id}
            className="group flex items-center justify-between rounded px-1.5 py-0.5 text-[10px] font-medium"
            style={{ backgroundColor: `color-mix(in srgb, ${color} 18%, transparent)` }}
          >
            <span>{slot.start_time.slice(0, 5)}–{slot.end_time.slice(0, 5)}</span>
            {canEdit && (
              <button
                className="opacity-0 group-hover:opacity-100 transition-opacity duration-100"
                onClick={() => onRemoveSlot(slot.id)}
                aria-label={`Remove ${slot.start_time.slice(0, 5)}–${slot.end_time.slice(0, 5)} shift`}
              >
                <X className="h-3 w-3" />
              </button>
            )}
          </div>
        ))}
        {canEdit && (
          <button
            className="flex items-center gap-0.5 text-[10px] text-muted-foreground hover:text-foreground transition-colors duration-100 w-full"
            onClick={() => onAddSlot(artistId, date)}
            aria-label={`Add slot for ${artistName} on ${dayLabel}`}
          >
            <Plus className="h-3 w-3" />Add
          </button>
        )}
      </div>
    )
  }

  // Empty cell
  if (canEdit) {
    return (
      <button
        className="flex h-full min-h-[72px] w-full items-center justify-center text-[10px] text-muted-foreground/50 hover:text-muted-foreground hover:bg-muted/20 rounded transition-colors duration-100"
        onClick={() => onAddSlot(artistId, date)}
        aria-label={`Add shift for ${artistName} on ${dayLabel}`}
      >
        <Plus className="h-3 w-3 mr-0.5" />
        Add
      </button>
    )
  }

  return <div className="h-full min-h-[72px]" />
}

'use client'

import { format, isToday } from 'date-fns'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Skeleton } from '@/components/ui/skeleton'
import { ScheduleCell } from './ScheduleCell'
import type { TimeOff } from './types'

interface ScheduleSlotRow {
  id: string
  artist_id: string
  start_time: string
  end_time: string
  day_of_week: number
}

interface ScheduleArtist {
  id: string
  display_name: string
  avatar_url: string | null
  calendar_color: string | null
}

interface ScheduleGridMobileProps {
  artists: ScheduleArtist[]
  weekDays: Date[]
  selectedArtistId: string
  onSelectArtist: (id: string) => void
  getSlots: (artistId: string, date: Date) => ScheduleSlotRow[]
  getTimeOff: (artistId: string, date: Date) => TimeOff | null
  canEdit: boolean
  loading: boolean
  onAddSlot: (artistId: string, date: Date) => void
  onRemoveSlot: (slotId: string) => void
}

export function ScheduleGridMobile({
  artists,
  weekDays,
  selectedArtistId,
  onSelectArtist,
  getSlots,
  getTimeOff,
  canEdit,
  loading,
  onAddSlot,
  onRemoveSlot,
}: ScheduleGridMobileProps) {
  const selectedArtist = artists.find((a) => a.id === selectedArtistId)

  if (loading) {
    return (
      <div className="space-y-3 px-4">
        <Skeleton className="h-10 w-full rounded-lg" />
        {Array.from({ length: 7 }).map((_, i) => (
          <Skeleton key={i} className="h-16 w-full rounded-lg" />
        ))}
      </div>
    )
  }

  return (
    <div className="space-y-3 px-4 pb-6">
      {/* Artist selector */}
      <Select value={selectedArtistId} onValueChange={onSelectArtist}>
        <SelectTrigger className="w-full" aria-label="Select artist">
          <SelectValue placeholder="Select artist" />
        </SelectTrigger>
        <SelectContent>
          {artists.map((a) => (
            <SelectItem key={a.id} value={a.id}>
              {a.display_name}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>

      {/* Day list */}
      {weekDays.map((day) => {
        const slots = selectedArtistId ? getSlots(selectedArtistId, day) : []
        const timeOff = selectedArtistId ? getTimeOff(selectedArtistId, day) : null

        return (
          <div
            key={day.toISOString()}
            className="rounded-lg border border-border/40 overflow-hidden"
          >
            <div
              className={`px-3 py-2 text-xs font-medium border-b border-border/30 ${
                isToday(day) ? 'text-primary bg-primary/5' : 'text-muted-foreground bg-muted/20'
              }`}
            >
              {format(day, 'EEEE, MMM d')}
            </div>
            <div className="p-2">
              <ScheduleCell
                artistId={selectedArtistId}
                artistName={selectedArtist?.display_name ?? ''}
                calendarColor={selectedArtist?.calendar_color ?? null}
                date={day}
                slots={slots}
                timeOff={timeOff}
                canEdit={canEdit}
                onAddSlot={onAddSlot}
                onRemoveSlot={onRemoveSlot}
              />
            </div>
          </div>
        )
      })}
    </div>
  )
}

'use client'

import { useState, useCallback, useEffect } from 'react'
import {
  startOfWeek,
  endOfWeek,
  addWeeks,
  subWeeks,
  eachDayOfInterval,
  format,
  isToday,
} from 'date-fns'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import {
  ChevronLeft,
  ChevronRight,
  ChevronDown,
  CalendarRange,
  Plus,
} from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { Skeleton } from '@/components/ui/skeleton'
import { Typography } from '@/components/ui/typography'
import { EmptyState } from '@/components/shared/EmptyState'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { toast } from 'sonner'
import { Loader2 } from 'lucide-react'
import { cn } from '@/lib/utils'
import { ScheduleCell } from '@/components/schedule/ScheduleCell'
import { ScheduleGridMobile } from '@/components/schedule/ScheduleGridMobile'
import { usePermissions } from '@/lib/team/permissions-context'
import type { TimeOff } from '@/components/schedule/types'

interface ArtistRow {
  id: string
  display_name: string
  avatar_url: string | null
  calendar_color: string | null
}

interface ScheduleSlotRow {
  id: string
  artist_id: string
  start_time: string
  end_time: string
  day_of_week: number
}

interface ScheduleTemplate {
  id: string
  name: string
  slots: Record<number, Array<{ start_time: string; end_time: string }>>
}

function getInitials(name: string): string {
  return name.split(' ').map((n) => n[0]).slice(0, 2).join('').toUpperCase()
}

export default function ArtistSchedulesPage() {
  const router = useRouter()
  const { canDo } = usePermissions()
  const canEdit = canDo('calendar.manage_any')

  const [weekStart, setWeekStart] = useState<Date>(() => startOfWeek(new Date(), { weekStartsOn: 1 }))
  const [artists, setArtists] = useState<ArtistRow[]>([])
  const [slots, setSlots] = useState<ScheduleSlotRow[]>([])
  const [timeOffMap, setTimeOffMap] = useState<TimeOff[]>([])
  const [templates, setTemplates] = useState<ScheduleTemplate[]>([])
  const [loading, setLoading] = useState(true)
  const [selectedMobileArtist, setSelectedMobileArtist] = useState<string>('')

  // Add slot dialog
  const [addSlotOpen, setAddSlotOpen] = useState(false)
  const [addSlotArtistId, setAddSlotArtistId] = useState<string>('')
  const [addSlotDate, setAddSlotDate] = useState<Date>(new Date())
  const [addSlotStart, setAddSlotStart] = useState('09:00')
  const [addSlotEnd, setAddSlotEnd] = useState('17:00')
  const [savingSlot, setSavingSlot] = useState(false)

  // Save template dialog
  const [saveTemplateOpen, setSaveTemplateOpen] = useState(false)
  const [templateName, setTemplateName] = useState('')
  const [savingTemplate, setSavingTemplate] = useState(false)

  const weekEnd = endOfWeek(weekStart, { weekStartsOn: 1 })
  const weekDays = eachDayOfInterval({ start: weekStart, end: weekEnd })

  const fetchData = useCallback(async () => {
    setLoading(true)
    try {
      const [artistsRes, slotsRes, timeOffRes, templatesRes] = await Promise.all([
        fetch('/api/artists'),
        fetch(`/api/schedule/week?from=${format(weekStart, 'yyyy-MM-dd')}&to=${format(weekEnd, 'yyyy-MM-dd')}`),
        fetch(`/api/schedule/time-off?from=${format(weekStart, 'yyyy-MM-dd')}&to=${format(weekEnd, 'yyyy-MM-dd')}`),
        fetch('/api/schedule/templates'),
      ])

      if (artistsRes.ok) {
        const json = await artistsRes.json() as { data: ArtistRow[] }
        const data = json.data ?? []
        setArtists(data)
        if (data.length > 0 && !selectedMobileArtist) {
          setSelectedMobileArtist(data[0]?.id ?? '')
        }
      }
      if (slotsRes.ok) {
        const json = await slotsRes.json() as { data: ScheduleSlotRow[] }
        setSlots(json.data ?? [])
      }
      if (timeOffRes.ok) {
        const json = await timeOffRes.json() as { data: TimeOff[] }
        setTimeOffMap(json.data ?? [])
      }
      if (templatesRes.ok) {
        const json = await templatesRes.json() as { data: ScheduleTemplate[] }
        setTemplates(json.data ?? [])
      }
    } catch {
      toast.error('Failed to load schedules')
    } finally {
      setLoading(false)
    }
  }, [weekStart, weekEnd, selectedMobileArtist])

  useEffect(() => { void fetchData() }, [fetchData])

  const prevWeek = () => setWeekStart((d) => subWeeks(d, 1))
  const nextWeek = () => setWeekStart((d) => addWeeks(d, 1))
  const goToday = () => setWeekStart(startOfWeek(new Date(), { weekStartsOn: 1 }))

  const getSlots = useCallback((artistId: string, date: Date): ScheduleSlotRow[] => {
    const dow = date.getDay()
    return slots.filter((s) => s.artist_id === artistId && s.day_of_week === dow)
  }, [slots])

  const getTimeOff = useCallback((artistId: string, date: Date): TimeOff | null => {
    const dateStr = format(date, 'yyyy-MM-dd')
    return timeOffMap.find((t) =>
      t.artist_id === artistId &&
      t.status === 'approved' &&
      t.start_at.slice(0, 10) <= dateStr &&
      t.end_at.slice(0, 10) >= dateStr
    ) ?? null
  }, [timeOffMap])

  const handleAddSlot = (artistId: string, date: Date) => {
    setAddSlotArtistId(artistId)
    setAddSlotDate(date)
    setAddSlotStart('09:00')
    setAddSlotEnd('17:00')
    setAddSlotOpen(true)
  }

  const handleSaveSlot = async () => {
    setSavingSlot(true)
    try {
      const res = await fetch(`/api/artists/${addSlotArtistId}/schedule`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          day_of_week: addSlotDate.getDay(),
          start_time: `${addSlotStart}:00`,
          end_time: `${addSlotEnd}:00`,
        }),
      })
      if (!res.ok) throw new Error('Failed to add slot')
      toast.success('Shift added')
      setAddSlotOpen(false)
      void fetchData()
    } catch {
      toast.error('Failed to add shift')
    } finally {
      setSavingSlot(false)
    }
  }

  const handleRemoveSlot = async (slotId: string) => {
    // Optimistic
    setSlots((prev) => prev.filter((s) => s.id !== slotId))
    try {
      const artistId = slots.find((s) => s.id === slotId)?.artist_id
      if (!artistId) return
      const res = await fetch(`/api/artists/${artistId}/schedule`, {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ids: [slotId] }),
      })
      if (!res.ok) throw new Error('Failed')
      toast.success('Shift removed')
    } catch {
      toast.error('Failed to remove shift')
      void fetchData()
    }
  }

  const handleCopyPreviousWeek = async () => {
    const prevWeekStart = format(subWeeks(weekStart, 1), 'yyyy-MM-dd')
    const prevWeekEnd = format(subWeeks(weekEnd, 1), 'yyyy-MM-dd')
    try {
      const res = await fetch('/api/schedule/copy-week', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          from_start: prevWeekStart,
          from_end: prevWeekEnd,
          to_start: format(weekStart, 'yyyy-MM-dd'),
        }),
      })
      if (!res.ok) throw new Error('Failed')
      toast.success('Previous week copied')
      void fetchData()
    } catch {
      toast.error('Failed to copy previous week')
    }
  }

  const handleApplyTemplate = async (template: ScheduleTemplate) => {
    try {
      const res = await fetch('/api/schedule/apply-template', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          template_id: template.id,
          week_start: format(weekStart, 'yyyy-MM-dd'),
        }),
      })
      if (!res.ok) throw new Error('Failed')
      toast.success(`Template "${template.name}" applied`)
      void fetchData()
    } catch {
      toast.error('Failed to apply template')
    }
  }

  const handleSaveTemplate = async () => {
    if (!templateName.trim()) return
    setSavingTemplate(true)
    try {
      const res = await fetch('/api/schedule/templates', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: templateName.trim(),
          week_start: format(weekStart, 'yyyy-MM-dd'),
        }),
      })
      if (!res.ok) throw new Error('Failed')
      toast.success(`Template "${templateName}" saved`)
      setSaveTemplateOpen(false)
      setTemplateName('')
      void fetchData()
    } catch {
      toast.error('Failed to save template')
    } finally {
      setSavingTemplate(false)
    }
  }

  if (loading && artists.length === 0) {
    return (
      <div className="flex flex-col min-h-0">
        {/* Toolbar skeleton */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-border/50">
          <Skeleton className="h-8 w-40" />
          <div className="flex items-center gap-2">
            <Skeleton className="h-8 w-48 rounded-lg" />
            <Skeleton className="h-8 w-24 rounded-lg" />
          </div>
        </div>
        {/* Grid skeleton */}
        <div className="overflow-auto p-2">
          <div className="grid" style={{ gridTemplateColumns: '180px repeat(7, minmax(120px,1fr))' }}>
            {Array.from({ length: 8 }).map((_, i) => (
              <div key={i} className="h-10 border-b border-r border-border/30 bg-muted/20 last:border-r-0" />
            ))}
            {Array.from({ length: 5 }).map((_, ri) =>
              Array.from({ length: 8 }).map((_, ci) => (
                <div key={`${ri}-${ci}`} className={cn('h-24 border-b border-r border-border/20 last:border-r-0 p-2', ci === 0 && 'flex items-center gap-2')}>
                  {ci === 0 ? (
                    <><Skeleton className="h-7 w-7 rounded-full" /><Skeleton className="h-4 w-20" /></>
                  ) : (
                    <Skeleton className="h-6 w-full rounded" />
                  )}
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="flex flex-col min-h-0">
      {/* Toolbar */}
      <div className="flex items-center justify-between flex-wrap gap-3 px-6 py-4 border-b border-border/50">
        <div>
          <Typography variant="h1">Artist Schedules</Typography>
          <p className="text-sm text-muted-foreground mt-0.5">
            Weekly availability for every artist.
          </p>
        </div>
        <div className="flex items-center gap-2">
          {/* Week picker */}
          <div className="flex items-center gap-1 rounded-lg border border-border bg-card px-2 py-1">
            <Button variant="ghost" size="icon" className="h-7 w-7" onClick={prevWeek} aria-label="Previous week">
              <ChevronLeft className="h-4 w-4" />
            </Button>
            <span className="text-sm font-medium w-32 text-center tabular-nums">
              {format(weekStart, 'MMM d')} – {format(weekEnd, 'MMM d')}
            </span>
            <Button variant="ghost" size="icon" className="h-7 w-7" onClick={nextWeek} aria-label="Next week">
              <ChevronRight className="h-4 w-4" />
            </Button>
            <Button variant="ghost" size="sm" className="h-7 text-xs ml-1" onClick={goToday}>
              Today
            </Button>
          </div>
          {/* Actions dropdown */}
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="outline" size="sm">
                Actions
                <ChevronDown className="ml-1.5 h-4 w-4" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end">
              <DropdownMenuItem onClick={() => void handleCopyPreviousWeek()}>
                Copy previous week
              </DropdownMenuItem>
              <DropdownMenuSeparator />
              <DropdownMenuSub>
                <DropdownMenuSubTrigger>Apply template</DropdownMenuSubTrigger>
                <DropdownMenuSubContent>
                  <DropdownMenuItem onClick={() => void handleApplyTemplate({ id: 'standard-9-5', name: 'Standard 9–5 Mon–Fri', slots: {} })}>
                    Standard 9–5 Mon–Fri
                  </DropdownMenuItem>
                  <DropdownMenuItem onClick={() => void handleApplyTemplate({ id: 'part-time-tue-thu', name: 'Part-time Tue / Thu', slots: {} })}>
                    Part-time Tue / Thu
                  </DropdownMenuItem>
                  <DropdownMenuItem onClick={() => void handleApplyTemplate({ id: 'weekend-only', name: 'Weekend only', slots: {} })}>
                    Weekend only
                  </DropdownMenuItem>
                  {templates.length > 0 && <DropdownMenuSeparator />}
                  {templates.map((t) => (
                    <DropdownMenuItem key={t.id} onClick={() => void handleApplyTemplate(t)}>
                      {t.name}
                    </DropdownMenuItem>
                  ))}
                  <DropdownMenuSeparator />
                  <DropdownMenuItem onClick={() => setSaveTemplateOpen(true)}>
                    Save current week as template…
                  </DropdownMenuItem>
                </DropdownMenuSubContent>
              </DropdownMenuSub>
              <DropdownMenuSeparator />
              <DropdownMenuItem onClick={() => window.print()}>
                Export PDF
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>

      {artists.length === 0 ? (
        <div className="flex flex-1 items-center justify-center p-8">
          <EmptyState
            icon={CalendarRange}
            title="No artists to schedule"
            description="Add artists to your studio first, then manage their weekly availability here."
            cta={{ label: 'Add artist', onClick: () => router.push('/artists/new') }}
            variant="first-time"
          />
        </div>
      ) : (
        <>
          {/* Mobile grid — hidden on md+ */}
          <div className="md:hidden">
            <ScheduleGridMobile
              artists={artists}
              weekDays={weekDays}
              selectedArtistId={selectedMobileArtist}
              onSelectArtist={setSelectedMobileArtist}
              getSlots={getSlots}
              getTimeOff={getTimeOff}
              canEdit={canEdit}
              loading={loading}
              onAddSlot={handleAddSlot}
              onRemoveSlot={(id) => void handleRemoveSlot(id)}
            />
          </div>

          {/* Desktop grid — hidden below md */}
          <div className="hidden md:block overflow-auto flex-1">
            <table className="w-full border-separate border-spacing-0 text-sm" role="grid">
              <thead>
                <tr>
                  <th
                    className="sticky left-0 z-20 w-[180px] bg-background border-b border-r border-border/50 px-4 py-2 text-left text-xs font-medium text-muted-foreground"
                    scope="col"
                  >
                    Artist
                  </th>
                  {weekDays.map((day) => (
                    <th
                      key={day.toISOString()}
                      className="min-w-[120px] border-b border-r border-border/30 px-3 py-2 text-center text-xs font-medium text-muted-foreground last:border-r-0"
                      scope="col"
                    >
                      <div>{format(day, 'EEE')}</div>
                      <div
                        className={cn(
                          'text-base font-semibold mt-0.5',
                          isToday(day) && 'text-primary',
                        )}
                      >
                        {format(day, 'd')}
                      </div>
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {artists.map((artist) => (
                  <tr key={artist.id} className="hover:bg-muted/10 transition-colors">
                    {/* Sticky artist cell */}
                    <th
                      className="sticky left-0 z-10 bg-background border-b border-r border-border/50 px-4 py-2 text-left font-normal"
                      scope="row"
                    >
                      <Link
                        href={`/artists/${artist.id}`}
                        className="flex items-center gap-2 group"
                      >
                        <Avatar className="h-7 w-7 shrink-0">
                          <AvatarImage src={artist.avatar_url ?? undefined} />
                          <AvatarFallback className="text-xs">
                            {getInitials(artist.display_name)}
                          </AvatarFallback>
                        </Avatar>
                        <span className="text-sm font-medium truncate max-w-[112px] group-hover:text-primary transition-colors">
                          {artist.display_name}
                        </span>
                      </Link>
                    </th>
                    {/* Day cells */}
                    {weekDays.map((day) => (
                      <td
                        key={day.toISOString()}
                        className="relative border-b border-r border-border/20 align-top p-1.5 min-h-[88px] last:border-r-0"
                      >
                        <ScheduleCell
                          artistId={artist.id}
                          artistName={artist.display_name}
                          calendarColor={artist.calendar_color}
                          date={day}
                          slots={getSlots(artist.id, day)}
                          timeOff={getTimeOff(artist.id, day)}
                          canEdit={canEdit}
                          onAddSlot={handleAddSlot}
                          onRemoveSlot={(id) => void handleRemoveSlot(id)}
                        />
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}

      {/* Add slot dialog */}
      <Dialog open={addSlotOpen} onOpenChange={setAddSlotOpen}>
        <DialogContent className="max-w-sm">
          <DialogHeader>
            <DialogTitle>Add Shift</DialogTitle>
            <DialogDescription>
              {artists.find((a) => a.id === addSlotArtistId)?.display_name} · {format(addSlotDate, 'EEEE, MMM d')}
            </DialogDescription>
          </DialogHeader>
          <div className="grid grid-cols-2 gap-3 py-2">
            <div className="space-y-1.5">
              <Label className="text-sm">Start time</Label>
              <Input
                type="time"
                value={addSlotStart}
                onChange={(e) => setAddSlotStart(e.target.value)}
              />
            </div>
            <div className="space-y-1.5">
              <Label className="text-sm">End time</Label>
              <Input
                type="time"
                value={addSlotEnd}
                min={addSlotStart}
                onChange={(e) => setAddSlotEnd(e.target.value)}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setAddSlotOpen(false)}>Cancel</Button>
            <Button onClick={() => void handleSaveSlot()} disabled={savingSlot}>
              {savingSlot ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : null}
              Add Shift
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Save template dialog */}
      <Dialog open={saveTemplateOpen} onOpenChange={setSaveTemplateOpen}>
        <DialogContent className="max-w-sm">
          <DialogHeader>
            <DialogTitle>Save as Template</DialogTitle>
          </DialogHeader>
          <div className="space-y-3 py-2">
            <div className="space-y-1.5">
              <Label>Template name</Label>
              <Input
                placeholder="e.g. Summer schedule"
                value={templateName}
                onChange={(e) => setTemplateName(e.target.value)}
              />
            </div>
            <p className="text-xs text-muted-foreground">
              Saves all {artists.length} artists&apos; shifts from this week as a reusable template.
            </p>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setSaveTemplateOpen(false)}>Cancel</Button>
            <Button
              onClick={() => void handleSaveTemplate()}
              disabled={!templateName.trim() || savingTemplate}
            >
              {savingTemplate ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : null}
              Save Template
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Needed API stubs notice (only in dev) — these endpoints need Dato migration */}
      {/* /api/schedule/week, /api/schedule/time-off, /api/schedule/templates, /api/schedule/copy-week, /api/schedule/apply-template */}
    </div>
  )
}

'use client'

import { useState, useCallback, useEffect } from 'react'
import {
  startOfWeek,
  endOfWeek,
  addWeeks,
  subWeeks,
  eachDayOfInterval,
  format,
  isToday,
} from 'date-fns'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import {
  ChevronLeft,
  ChevronRight,
  ChevronDown,
  CalendarRange,
} from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { Skeleton } from '@/components/ui/skeleton'
import { Typography } from '@/components/ui/typography'
import { EmptyState } from '@/components/shared/EmptyState'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { toast } from 'sonner'
import { Loader2 } from 'lucide-react'
import { cn } from '@/lib/utils'
import { ScheduleCell } from '@/components/schedule/ScheduleCell'
import { ScheduleGridMobile } from '@/components/schedule/ScheduleGridMobile'
import { usePermissions } from '@/lib/team/permissions-context'
import type { TimeOff } from '@/components/schedule/types'

interface ArtistRow {
  id: string
  display_name: string
  avatar_url: string | null
  calendar_color: string | null
}

interface ScheduleSlotRow {
  id: string
  artist_id: string
  start_time: string
  end_time: string
  day_of_week: number
}

interface ScheduleTemplate {
  id: string
  name: string
  slots: Record<number, Array<{ start_time: string; end_time: string }>>
}

function getInitials(name: string): string {
  return name.split(' ').map((n) => n[0]).slice(0, 2).join('').toUpperCase()
}

export default function ArtistSchedulesPage() {
  const router = useRouter()
  const { canDo } = usePermissions()
  const canEdit = canDo('calendar.manage_any')

  const [weekStart, setWeekStart] = useState<Date>(() =>
    startOfWeek(new Date(), { weekStartsOn: 1 })
  )
  const [artists, setArtists] = useState<ArtistRow[]>([])
  const [slots, setSlots] = useState<ScheduleSlotRow[]>([])
  const [timeOffList, setTimeOffList] = useState<TimeOff[]>([])
  const [templates, setTemplates] = useState<ScheduleTemplate[]>([])
  const [loading, setLoading] = useState(true)
  const [selectedMobileArtist, setSelectedMobileArtist] = useState<string>('')

  // Add slot dialog
  const [addSlotOpen, setAddSlotOpen] = useState(false)
  const [addSlotArtistId, setAddSlotArtistId] = useState<string>('')
  const [addSlotDate, setAddSlotDate] = useState<Date>(new Date())
  const [addSlotStart, setAddSlotStart] = useState('09:00')
  const [addSlotEnd, setAddSlotEnd] = useState('17:00')
  const [savingSlot, setSavingSlot] = useState(false)

  // Save template dialog
  const [saveTemplateOpen, setSaveTemplateOpen] = useState(false)
  const [templateName, setTemplateName] = useState('')
  const [savingTemplate, setSavingTemplate] = useState(false)

  const weekEnd = endOfWeek(weekStart, { weekStartsOn: 1 })
  const weekDays = eachDayOfInterval({ start: weekStart, end: weekEnd })

  const fetchData = useCallback(async () => {
    setLoading(true)
    try {
      const artistsRes = await fetch('/api/artists')
      if (artistsRes.ok) {
        const json = await artistsRes.json() as { data: ArtistRow[] }
        const data = json.data ?? []
        setArtists(data)
        if (data.length > 0 && !selectedMobileArtist) {
          setSelectedMobileArtist(data[0]?.id ?? '')
        }
      }

      // Fetch per-artist schedule slots for the week
      const from = format(weekStart, 'yyyy-MM-dd')
      const to = format(weekEnd, 'yyyy-MM-dd')

      const [slotsRes, timeOffRes, templatesRes] = await Promise.allSettled([
        fetch(`/api/schedule/week?from=${from}&to=${to}`),
        fetch(`/api/schedule/time-off?from=${from}&to=${to}`),
        fetch('/api/schedule/templates'),
      ])

      if (slotsRes.status === 'fulfilled' && slotsRes.value.ok) {
        const json = await slotsRes.value.json() as { data: ScheduleSlotRow[] }
        setSlots(json.data ?? [])
      }
      if (timeOffRes.status === 'fulfilled' && timeOffRes.value.ok) {
        const json = await timeOffRes.value.json() as { data: TimeOff[] }
        setTimeOffList(json.data ?? [])
      }
      if (templatesRes.status === 'fulfilled' && templatesRes.value.ok) {
        const json = await templatesRes.value.json() as { data: ScheduleTemplate[] }
        setTemplates(json.data ?? [])
      }
    } catch {
      toast.error('Failed to load schedules')
    } finally {
      setLoading(false)
    }
  }, [weekStart, weekEnd, selectedMobileArtist])

  useEffect(() => { void fetchData() }, [fetchData])

  const prevWeek = () => setWeekStart((d) => subWeeks(d, 1))
  const nextWeek = () => setWeekStart((d) => addWeeks(d, 1))
  const goToday = () => setWeekStart(startOfWeek(new Date(), { weekStartsOn: 1 }))

  const getSlots = useCallback(
    (artistId: string, date: Date): ScheduleSlotRow[] => {
      const dow = date.getDay()
      return slots.filter((s) => s.artist_id === artistId && s.day_of_week === dow)
    },
    [slots]
  )

  const getTimeOff = useCallback(
    (artistId: string, date: Date): TimeOff | null => {
      const dateStr = format(date, 'yyyy-MM-dd')
      return (
        timeOffList.find(
          (t) =>
            t.artist_id === artistId &&
            t.status === 'approved' &&
            t.start_at.slice(0, 10) <= dateStr &&
            t.end_at.slice(0, 10) >= dateStr
        ) ?? null
      )
    },
    [timeOffList]
  )

  const handleAddSlot = (artistId: string, date: Date) => {
    setAddSlotArtistId(artistId)
    setAddSlotDate(date)
    setAddSlotStart('09:00')
    setAddSlotEnd('17:00')
    setAddSlotOpen(true)
  }

  const handleSaveSlot = async () => {
    setSavingSlot(true)
    try {
      const res = await fetch(`/api/artists/${addSlotArtistId}/schedule`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          day_of_week: addSlotDate.getDay(),
          start_time: `${addSlotStart}:00`,
          end_time: `${addSlotEnd}:00`,
        }),
      })
      if (!res.ok) throw new Error('Failed to add slot')
      toast.success('Shift added')
      setAddSlotOpen(false)
      void fetchData()
    } catch {
      toast.error('Failed to add shift')
    } finally {
      setSavingSlot(false)
    }
  }

  const handleRemoveSlot = async (slotId: string) => {
    // Optimistic removal
    const artist = artists.find((a) => getSlots(a.id, addSlotDate).some((s) => s.id === slotId))
    const slot = slots.find((s) => s.id === slotId)
    setSlots((prev) => prev.filter((s) => s.id !== slotId))
    try {
      const artistId = slot?.artist_id
      if (!artistId) return
      const res = await fetch(`/api/artists/${artistId}/schedule`, {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ids: [slotId] }),
      })
      if (!res.ok) throw new Error('Failed')
      toast.success('Shift removed')
    } catch {
      toast.error('Failed to remove shift')
      void fetchData()
    }
  }

  const handleCopyPreviousWeek = async () => {
    const from = format(subWeeks(weekStart, 1), 'yyyy-MM-dd')
    const fromEnd = format(subWeeks(weekEnd, 1), 'yyyy-MM-dd')
    try {
      const res = await fetch('/api/schedule/copy-week', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          from_start: from,
          from_end: fromEnd,
          to_start: format(weekStart, 'yyyy-MM-dd'),
        }),
      })
      if (!res.ok) throw new Error('Failed')
      toast.success('Previous week copied')
      void fetchData()
    } catch {
      toast.error('Failed to copy previous week')
    }
  }

  const handleApplyTemplate = async (template: ScheduleTemplate) => {
    try {
      const res = await fetch('/api/schedule/apply-template', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          template_id: template.id,
          week_start: format(weekStart, 'yyyy-MM-dd'),
        }),
      })
      if (!res.ok) throw new Error('Failed')
      toast.success(`Template "${template.name}" applied`)
      void fetchData()
    } catch {
      toast.error('Failed to apply template')
    }
  }

  const handleSaveTemplate = async () => {
    if (!templateName.trim()) return
    setSavingTemplate(true)
    try {
      const res = await fetch('/api/schedule/templates', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: templateName.trim(),
          week_start: format(weekStart, 'yyyy-MM-dd'),
        }),
      })
      if (!res.ok) throw new Error('Failed')
      toast.success(`Template "${templateName}" saved`)
      setSaveTemplateOpen(false)
      setTemplateName('')
      void fetchData()
    } catch {
      toast.error('Failed to save template')
    } finally {
      setSavingTemplate(false)
    }
  }

  if (loading && artists.length === 0) {
    return (
      <div className="flex flex-col min-h-0">
        <div className="flex items-center justify-between px-6 py-4 border-b border-border/50">
          <Skeleton className="h-8 w-40" />
          <div className="flex items-center gap-2">
            <Skeleton className="h-8 w-48 rounded-lg" />
            <Skeleton className="h-8 w-24 rounded-lg" />
          </div>
        </div>
        <div className="overflow-auto p-2">
          <div className="grid" style={{ gridTemplateColumns: '180px repeat(7, minmax(120px,1fr))' }}>
            {Array.from({ length: 8 }).map((_, i) => (
              <div key={i} className="h-10 border-b border-r border-border/30 bg-muted/20 last:border-r-0" />
            ))}
            {Array.from({ length: 5 }).map((_, ri) =>
              Array.from({ length: 8 }).map((_, ci) => (
                <div
                  key={`${ri}-${ci}`}
                  className={cn(
                    'h-24 border-b border-r border-border/20 last:border-r-0 p-2',
                    ci === 0 && 'flex items-center gap-2'
                  )}
                >
                  {ci === 0 ? (
                    <>
                      <Skeleton className="h-7 w-7 rounded-full" />
                      <Skeleton className="h-4 w-20" />
                    </>
                  ) : (
                    <Skeleton className="h-6 w-full rounded" />
                  )}
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="flex flex-col min-h-0">
      {/* Toolbar */}
      <div className="flex items-center justify-between flex-wrap gap-3 px-6 py-4 border-b border-border/50">
        <div>
          <Typography variant="h1">Artist Schedules</Typography>
          <p className="text-sm text-muted-foreground mt-0.5">
            Weekly availability for every artist.
          </p>
        </div>
        <div className="flex items-center gap-2">
          {/* Week picker */}
          <div className="flex items-center gap-1 rounded-lg border border-border bg-card px-2 py-1">
            <Button
              variant="ghost"
              size="icon"
              className="h-7 w-7"
              onClick={prevWeek}
              aria-label="Previous week"
            >
              <ChevronLeft className="h-4 w-4" />
            </Button>
            <span className="text-sm font-medium w-32 text-center tabular-nums">
              {format(weekStart, 'MMM d')} – {format(weekEnd, 'MMM d')}
            </span>
            <Button
              variant="ghost"
              size="icon"
              className="h-7 w-7"
              onClick={nextWeek}
              aria-label="Next week"
            >
              <ChevronRight className="h-4 w-4" />
            </Button>
            <Button
              variant="ghost"
              size="sm"
              className="h-7 text-xs ml-1"
              onClick={goToday}
            >
              Today
            </Button>
          </div>
          {/* Actions dropdown */}
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="outline" size="sm">
                Actions
                <ChevronDown className="ml-1.5 h-4 w-4" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end">
              <DropdownMenuItem onClick={() => void handleCopyPreviousWeek()}>
                Copy previous week
              </DropdownMenuItem>
              <DropdownMenuSeparator />
              <DropdownMenuSub>
                <DropdownMenuSubTrigger>Apply template</DropdownMenuSubTrigger>
                <DropdownMenuSubContent>
                  <DropdownMenuItem
                    onClick={() =>
                      void handleApplyTemplate({
                        id: 'standard-9-5',
                        name: 'Standard 9–5 Mon–Fri',
                        slots: {},
                      })
                    }
                  >
                    Standard 9–5 Mon–Fri
                  </DropdownMenuItem>
                  <DropdownMenuItem
                    onClick={() =>
                      void handleApplyTemplate({
                        id: 'part-time-tue-thu',
                        name: 'Part-time Tue / Thu',
                        slots: {},
                      })
                    }
                  >
                    Part-time Tue / Thu
                  </DropdownMenuItem>
                  <DropdownMenuItem
                    onClick={() =>
                      void handleApplyTemplate({
                        id: 'weekend-only',
                        name: 'Weekend only',
                        slots: {},
                      })
                    }
                  >
                    Weekend only
                  </DropdownMenuItem>
                  {templates.length > 0 && <DropdownMenuSeparator />}
                  {templates.map((t) => (
                    <DropdownMenuItem
                      key={t.id}
                      onClick={() => void handleApplyTemplate(t)}
                    >
                      {t.name}
                    </DropdownMenuItem>
                  ))}
                  <DropdownMenuSeparator />
                  <DropdownMenuItem onClick={() => setSaveTemplateOpen(true)}>
                    Save current week as template…
                  </DropdownMenuItem>
                </DropdownMenuSubContent>
              </DropdownMenuSub>
              <DropdownMenuSeparator />
              <DropdownMenuItem onClick={() => window.print()}>
                Export PDF
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>

      {artists.length === 0 ? (
        <div className="flex flex-1 items-center justify-center p-8">
          <EmptyState
            icon={CalendarRange}
            title="No artists to schedule"
            description="Add artists to your studio first, then manage their weekly availability here."
            cta={{ label: 'Add artist', onClick: () => router.push('/artists/new') }}
            variant="first-time"
          />
        </div>
      ) : (
        <>
          {/* Mobile layout — shown below md */}
          <div className="md:hidden">
            <ScheduleGridMobile
              artists={artists}
              weekDays={weekDays}
              selectedArtistId={selectedMobileArtist}
              onSelectArtist={setSelectedMobileArtist}
              getSlots={getSlots}
              getTimeOff={getTimeOff}
              canEdit={canEdit}
              loading={loading}
              onAddSlot={handleAddSlot}
              onRemoveSlot={(id) => void handleRemoveSlot(id)}
            />
          </div>

          {/* Desktop grid — shown on md+ */}
          <div className="hidden md:block overflow-auto flex-1">
            <table
              className="w-full border-separate border-spacing-0 text-sm"
              role="grid"
            >
              <thead>
                <tr>
                  <th
                    className="sticky left-0 z-20 w-[180px] bg-background border-b border-r border-border/50 px-4 py-2 text-left text-xs font-medium text-muted-foreground"
                    scope="col"
                  >
                    Artist
                  </th>
                  {weekDays.map((day) => (
                    <th
                      key={day.toISOString()}
                      className="min-w-[120px] border-b border-r border-border/30 px-3 py-2 text-center text-xs font-medium text-muted-foreground last:border-r-0"
                      scope="col"
                    >
                      <div>{format(day, 'EEE')}</div>
                      <div
                        className={cn(
                          'text-base font-semibold mt-0.5',
                          isToday(day) && 'text-primary'
                        )}
                      >
                        {format(day, 'd')}
                      </div>
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {artists.map((artist) => (
                  <tr
                    key={artist.id}
                    className="hover:bg-muted/10 transition-colors"
                  >
                    {/* Sticky artist name */}
                    <th
                      className="sticky left-0 z-10 bg-background border-b border-r border-border/50 px-4 py-2 text-left font-normal"
                      scope="row"
                    >
                      <Link
                        href={`/artists/${artist.id}`}
                        className="flex items-center gap-2 group"
                      >
                        <Avatar className="h-7 w-7 shrink-0">
                          <AvatarImage src={artist.avatar_url ?? undefined} />
                          <AvatarFallback className="text-xs">
                            {getInitials(artist.display_name)}
                          </AvatarFallback>
                        </Avatar>
                        <span className="text-sm font-medium truncate max-w-[112px] group-hover:text-primary transition-colors">
                          {artist.display_name}
                        </span>
                      </Link>
                    </th>
                    {/* Day cells */}
                    {weekDays.map((day) => (
                      <td
                        key={day.toISOString()}
                        className="relative border-b border-r border-border/20 align-top p-1.5 min-h-[88px] last:border-r-0"
                      >
                        <ScheduleCell
                          artistId={artist.id}
                          artistName={artist.display_name}
                          calendarColor={artist.calendar_color}
                          date={day}
                          slots={getSlots(artist.id, day)}
                          timeOff={getTimeOff(artist.id, day)}
                          canEdit={canEdit}
                          onAddSlot={handleAddSlot}
                          onRemoveSlot={(id) => void handleRemoveSlot(id)}
                        />
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}

      {/* Add slot dialog */}
      <Dialog open={addSlotOpen} onOpenChange={setAddSlotOpen}>
        <DialogContent className="max-w-sm">
          <DialogHeader>
            <DialogTitle>Add Shift</DialogTitle>
            <DialogDescription>
              {artists.find((a) => a.id === addSlotArtistId)?.display_name} ·{' '}
              {format(addSlotDate, 'EEEE, MMM d')}
            </DialogDescription>
          </DialogHeader>
          <div className="grid grid-cols-2 gap-3 py-2">
            <div className="space-y-1.5">
              <Label className="text-sm">Start time</Label>
              <Input
                type="time"
                value={addSlotStart}
                onChange={(e) => setAddSlotStart(e.target.value)}
              />
            </div>
            <div className="space-y-1.5">
              <Label className="text-sm">End time</Label>
              <Input
                type="time"
                value={addSlotEnd}
                min={addSlotStart}
                onChange={(e) => setAddSlotEnd(e.target.value)}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setAddSlotOpen(false)}>
              Cancel
            </Button>
            <Button onClick={() => void handleSaveSlot()} disabled={savingSlot}>
              {savingSlot ? (
                <Loader2 className="h-4 w-4 animate-spin mr-2" />
              ) : null}
              Add Shift
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Save template dialog */}
      <Dialog open={saveTemplateOpen} onOpenChange={setSaveTemplateOpen}>
        <DialogContent className="max-w-sm">
          <DialogHeader>
            <DialogTitle>Save as Template</DialogTitle>
          </DialogHeader>
          <div className="space-y-3 py-2">
            <div className="space-y-1.5">
              <Label>Template name</Label>
              <Input
                placeholder="e.g. Summer schedule"
                value={templateName}
                onChange={(e) => setTemplateName(e.target.value)}
              />
            </div>
            <p className="text-xs text-muted-foreground">
              Saves all {artists.length} artists&apos; shifts from this week as a
              reusable template.
            </p>
          </div>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setSaveTemplateOpen(false)}
            >
              Cancel
            </Button>
            <Button
              onClick={() => void handleSaveTemplate()}
              disabled={!templateName.trim() || savingTemplate}
            >
              {savingTemplate ? (
                <Loader2 className="h-4 w-4 animate-spin mr-2" />
              ) : null}
              Save Template
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { toast } from 'sonner'
import { Loader2, AlertTriangle, CheckCircle2, Clock } from 'lucide-react'
import { TIME_OFF_REASON_LABEL } from './types'
import type { TimeOffReason } from './types'

interface TimeOffModalProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  artistId: string
  isOwner: boolean
  onSuccess: () => void
}

export function TimeOffModal({
  open,
  onOpenChange,
  artistId,
  isOwner,
  onSuccess,
}: TimeOffModalProps) {
  const [startDate, setStartDate] = useState('')
  const [endDate, setEndDate] = useState('')
  const [reason, setReason] = useState<TimeOffReason | ''>('')
  const [notes, setNotes] = useState('')
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)

  // Conflict detection state
  const [conflictCount, setConflictCount] = useState<number | null>(null)
  const [checkingConflicts, setCheckingConflicts] = useState(false)

  const checkConflicts = async () => {
    if (!startDate || !endDate) return
    setCheckingConflicts(true)
    setConflictCount(null)
    try {
      const res = await fetch(
        `/api/artists/${artistId}/bookings?from=${startDate}&to=${endDate}&count_only=true`
      )
      if (!res.ok) return // Silent — don't block the form
      const json = await res.json() as { count: number }
      setConflictCount(json.count ?? 0)
    } catch {
      // Silent — don't block the form on conflict check error
    } finally {
      setCheckingConflicts(false)
    }
  }

  // Check conflicts when both dates are set and valid
  useEffect(() => {
    if (startDate && endDate && endDate >= startDate) {
      const timer = setTimeout(() => { void checkConflicts() }, 500)
      return () => clearTimeout(timer)
    } else {
      setConflictCount(null)
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [startDate, endDate])

  const handleSave = async () => {
    if (!startDate || !endDate) {
      setError('Start and end dates are required.')
      return
    }
    if (startDate > endDate) {
      setError('End date must be on or after start date.')
      return
    }
    setError(null)
    setSaving(true)
    try {
      const res = await fetch(`/api/artists/${artistId}/time-off`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          start_at: `${startDate}T00:00:00.000Z`,
          end_at: `${endDate}T23:59:59.000Z`,
          reason: reason || null,
          notes: notes.trim() || null,
        }),
      })
      if (!res.ok) {
        const json = await res.json() as { error?: string }
        throw new Error(json.error ?? 'Failed to submit time off')
      }
      toast.success('Time off submitted')
      onSuccess()
      onOpenChange(false)
      // Reset form
      setStartDate('')
      setEndDate('')
      setReason('')
      setNotes('')
      setConflictCount(null)
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to submit time off'
      toast.error(message)
    } finally {
      setSaving(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>Request Time Off</DialogTitle>
        </DialogHeader>

        <div className="space-y-4 py-2">
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <Label className="text-sm">Start date</Label>
              <Input
                type="date"
                value={startDate}
                onChange={(e) => setStartDate(e.target.value)}
              />
            </div>
            <div className="space-y-1.5">
              <Label className="text-sm">End date</Label>
              <Input
                type="date"
                value={endDate}
                min={startDate || undefined}
                onChange={(e) => setEndDate(e.target.value)}
              />
            </div>
          </div>

          {/* Conflict warning — warns but does NOT block submission */}
          {checkingConflicts && (
            <div className="flex items-center gap-2 rounded-lg bg-muted/30 px-3 py-2 text-xs text-muted-foreground">
              <Loader2 className="h-3.5 w-3.5 animate-spin shrink-0" />
              Checking for scheduling conflicts…
            </div>
          )}
          {!checkingConflicts && conflictCount !== null && conflictCount > 0 && (
            <div
              className="flex items-start gap-2 rounded-lg border border-amber-200 bg-amber-50 dark:border-amber-800/30 dark:bg-amber-900/20 p-3 text-sm text-amber-800 dark:text-amber-300 motion-safe:animate-in motion-safe:fade-in-0 duration-150"
              role="status"
            >
              <AlertTriangle className="h-4 w-4 mt-0.5 shrink-0" />
              <div>
                <p className="font-medium">
                  {conflictCount} appointment{conflictCount !== 1 ? 's' : ''} during this period
                </p>
                <p className="text-xs mt-0.5">
                  These appointments will not be cancelled automatically. You should
                  reschedule them before taking time off.
                </p>
              </div>
            </div>
          )}

          <div className="space-y-1.5">
            <Label className="text-sm">Reason</Label>
            <Select
              value={reason}
              onValueChange={(v) => setReason(v as TimeOffReason | '')}
            >
              <SelectTrigger>
                <SelectValue placeholder="Select reason (optional)" />
              </SelectTrigger>
              <SelectContent>
                {(Object.keys(TIME_OFF_REASON_LABEL) as TimeOffReason[]).map((key) => (
                  <SelectItem key={key} value={key}>
                    {TIME_OFF_REASON_LABEL[key]}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-1.5">
            <Label className="text-sm">Notes (optional)</Label>
            <Textarea
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              rows={3}
              maxLength={500}
              placeholder="Additional context..."
            />
          </div>

          {/* Approval status notice */}
          {isOwner ? (
            <div className="flex items-center gap-2 rounded-lg bg-muted/30 px-3 py-2 text-xs text-muted-foreground">
              <CheckCircle2 className="h-3.5 w-3.5 text-emerald-500 shrink-0" />
              As an owner, your time-off requests are automatically approved.
            </div>
          ) : (
            <div className="flex items-center gap-2 rounded-lg bg-muted/30 px-3 py-2 text-xs text-muted-foreground">
              <Clock className="h-3.5 w-3.5 shrink-0" />
              Your request will be sent to your studio owner for approval.
            </div>
          )}

          {error && (
            <p className="text-sm text-destructive" role="alert">
              {error}
            </p>
          )}
        </div>

        <DialogFooter>
          <Button
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={saving}
          >
            Cancel
          </Button>
          <Button onClick={() => void handleSave()} disabled={saving}>
            {saving ? (
              <><Loader2 className="mr-2 h-4 w-4 animate-spin" />Saving…</>
            ) : (
              'Submit Request'
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

