'use client'

import { useState, useEffect } from 'react'
import Link from 'next/link'
import { Check, X, Loader2, AlertCircle, Crown, Shield, Palette, Phone, Plus } from 'lucide-react'
import { Skeleton } from '@/components/ui/skeleton'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { Card, CardContent } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { cn } from '@/lib/utils'
import { toast } from 'sonner'

const ROLES = ['owner', 'admin', 'artist', 'receptionist', 'guest_artist'] as const
type Role = (typeof ROLES)[number]

const ROLE_LABEL: Record<Role, string> = {
  owner: 'Owner',
  admin: 'Admin',
  artist: 'Artist',
  receptionist: 'Receptionist',
  guest_artist: 'Guest Artist',
}

const ROLE_CLASS: Record<Role, string> = {
  owner:        'chip-role-owner',
  admin:        'chip-role-admin',
  artist:       'chip-role-artist',
  receptionist: 'chip-role-receptionist',
  guest_artist: 'chip-role-guest-artist',
}

// Role summary card data
const ROLE_SUMMARIES: Array<{
  role: Role
  icon: React.ComponentType<{ className?: string }>
  description: string
}> = [
  {
    role: 'owner',
    icon: Crown,
    description: 'Full studio control. Billing, deletion, role management. Cannot be revoked.',
  },
  {
    role: 'admin',
    icon: Shield,
    description: 'Manage all operations. No billing or studio deletion.',
  },
  {
    role: 'artist',
    icon: Palette,
    description: 'Own bookings, schedule, clients, and commission view.',
  },
  {
    role: 'receptionist',
    icon: Phone,
    description: 'Book and manage all appointments. No payroll or financial settings.',
  },
]

// Display groups and their permission keys
const PERMISSION_GROUPS: Array<{
  group: string
  permissions: Array<{ key: string; label: string }>
}> = [
  {
    group: 'Bookings',
    permissions: [
      { key: 'bookings.view_all', label: 'View all bookings' },
      { key: 'bookings.create', label: 'Create bookings' },
      { key: 'bookings.edit', label: 'Edit bookings' },
      { key: 'bookings.cancel', label: 'Cancel bookings' },
      { key: 'bookings.view_own', label: 'View own bookings only' },
    ],
  },
  {
    group: 'Clients',
    permissions: [
      { key: 'clients.view', label: 'View clients' },
      { key: 'clients.create', label: 'Create clients' },
      { key: 'clients.edit', label: 'Edit clients' },
      { key: 'clients.delete', label: 'Delete clients' },
      { key: 'clients.export', label: 'Export client data' },
    ],
  },
  {
    group: 'Artists',
    permissions: [
      { key: 'artists.view', label: 'View artist profiles' },
      { key: 'artists.create', label: 'Add artists' },
      { key: 'artists.edit', label: 'Edit artist profiles' },
      { key: 'artists.deactivate', label: 'Deactivate artists' },
      { key: 'artists.view_commission', label: 'View commission rates' },
      { key: 'artists.edit_commission', label: 'Edit commission rates' },
    ],
  },
  {
    group: 'Team & Roles',
    permissions: [
      { key: 'team.view', label: 'View team members' },
      { key: 'team.invite', label: 'Invite members' },
      { key: 'admin.change_roles', label: 'Change member roles' },
      { key: 'admin.deactivate_members', label: 'Deactivate members' },
    ],
  },
  {
    group: 'Settings & Admin',
    permissions: [
      { key: 'settings.view', label: 'View settings' },
      { key: 'settings.edit', label: 'Edit settings' },
      { key: 'admin.billing', label: 'Manage billing' },
      { key: 'admin.integrations', label: 'Manage integrations' },
      { key: 'admin.audit_log', label: 'View audit log' },
    ],
  },
  {
    group: 'Services',
    permissions: [
      { key: 'services.view', label: 'View services' },
      { key: 'services.create', label: 'Create services' },
      { key: 'services.edit', label: 'Edit services' },
      { key: 'services.delete', label: 'Delete services' },
    ],
  },
]

type PermissionsData = Record<string, Record<string, boolean>>

interface PermissionsMatrixProps {
  isPro?: boolean
  canEdit?: boolean
}

export function PermissionsMatrix({ isPro = false, canEdit = false }: PermissionsMatrixProps) {
  const [data, setData] = useState<PermissionsData | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [resetTarget, setResetTarget] = useState<Role | null>(null)
  const [resetting, setResetting] = useState(false)

  useEffect(() => {
    void (async () => {
      try {
        const res = await fetch('/api/role-permissions')
        if (!res.ok) {
          setError('Failed to load permissions')
          return
        }
        const json = await res.json() as { data: PermissionsData }
        setData(json.data ?? {})
      } catch {
        setError('Could not connect to server')
      } finally {
        setLoading(false)
      }
    })()
  }, [])

  const handleReset = async (role: Role) => {
    setResetting(true)
    try {
      const res = await fetch(`/api/role-permissions/${role}/reset`, { method: 'POST' })
      if (!res.ok) throw new Error('Failed to reset')
      toast.success(`${ROLE_LABEL[role]} permissions reset to defaults`)
      // Refetch
      const refreshRes = await fetch('/api/role-permissions')
      if (refreshRes.ok) {
        const json = await refreshRes.json() as { data: PermissionsData }
        setData(json.data ?? {})
      }
    } catch {
      toast.error('Failed to reset permissions')
    } finally {
      setResetting(false)
      setResetTarget(null)
    }
  }

  function isGranted(role: Role, key: string): boolean {
    return data?.[role]?.[key] ?? false
  }

  function countGranted(role: Role): number {
    if (!data?.[role]) return 0
    return Object.values(data[role]).filter(Boolean).length
  }

  const totalPermissions = PERMISSION_GROUPS.reduce((sum, g) => sum + g.permissions.length, 0)

  if (loading) {
    return (
      <div className="space-y-3">
        {Array.from({ length: 6 }).map((_, i) => (
          <Skeleton key={i} className="h-10 rounded-lg" />
        ))}
      </div>
    )
  }

  if (error) {
    return (
      <Alert variant="destructive">
        <AlertCircle className="h-4 w-4" />
        <AlertDescription>{error}</AlertDescription>
      </Alert>
    )
  }

  return (
    <div className="space-y-6">
      {/* Role summary cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
        {ROLE_SUMMARIES.map((r) => {
          const Icon = r.icon
          const granted = data ? countGranted(r.role) : 0
          return (
            <Card
              key={r.role}
              className="shadow-soft motion-safe:animate-in motion-safe:fade-in-0 motion-safe:slide-in-from-bottom-1 duration-150"
            >
              <CardContent className="p-4">
                <div className="flex items-center gap-2 mb-2">
                  <Icon className="h-4 w-4 text-muted-foreground" />
                  <span
                    className={cn(
                      'inline-flex h-5 items-center rounded-full px-2 text-[10px] font-medium',
                      ROLE_CLASS[r.role]
                    )}
                  >
                    {ROLE_LABEL[r.role]}
                  </span>
                </div>
                <p className="text-xs text-muted-foreground leading-relaxed">
                  {r.description}
                </p>
                <p
                  className="text-[10px] text-muted-foreground mt-2 font-medium"
                  aria-label={`${granted} of ${totalPermissions} permissions granted`}
                >
                  {data ? `${granted} of ${totalPermissions}` : '—'} permissions
                </p>
              </CardContent>
            </Card>
          )
        })}
      </div>

      {/* Amber notice */}
      <div className="rounded-lg border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-800 dark:border-amber-800/30 dark:bg-amber-900/20 dark:text-amber-300">
        <p className="font-medium">Role permissions are plan-managed</p>
        <p className="text-xs mt-0.5">
          Permissions are set at the InkOS plan level. Custom role editing is available on Pro and
          above.
          <Link href="/settings/billing" className="ml-1 underline font-medium">
            View plans →
          </Link>
        </p>
      </div>

      {/* Matrix table */}
      <div className="w-full overflow-x-auto rounded-lg border border-border/50">
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b border-border/50 bg-muted/40">
              <th className="px-4 py-3 text-left font-medium text-muted-foreground w-[240px]">
                Permission
              </th>
              {ROLES.map((role) => (
                <th
                  key={role}
                  className="px-3 py-3 text-center font-medium text-foreground min-w-[100px]"
                >
                  <div className="flex flex-col items-center gap-1">
                    <span
                      className={cn(
                        'inline-flex h-5 items-center rounded-full px-2 text-[10px] font-medium',
                        ROLE_CLASS[role]
                      )}
                    >
                      {ROLE_LABEL[role]}
                    </span>
                    {role !== 'owner' && canEdit && (
                      <button
                        className="text-[9px] text-muted-foreground/60 hover:text-muted-foreground transition-colors duration-100"
                        onClick={() => setResetTarget(role)}
                        aria-label={`Reset ${ROLE_LABEL[role]} to defaults`}
                      >
                        Reset
                      </button>
                    )}
                  </div>
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {PERMISSION_GROUPS.map((group, gi) => (
              <>
                {/* Group header row */}
                <tr
                  key={`group-${gi}`}
                  className="bg-muted/20 border-t border-border/30 first:border-t-0 sticky top-[41px] z-10"
                >
                  <td
                    colSpan={ROLES.length + 1}
                    className="px-4 py-2 text-xs font-semibold uppercase tracking-wider text-muted-foreground"
                  >
                    {group.group}
                  </td>
                </tr>
                {/* Permission rows */}
                {group.permissions.map((perm, pi) => (
                  <tr
                    key={perm.key}
                    className={cn(
                      'border-t border-border/20 transition-colors hover:bg-muted/20',
                      pi === group.permissions.length - 1 && 'border-b border-border/30'
                    )}
                  >
                    <td className="px-4 py-2.5 text-foreground">
                      {perm.label}
                      <span className="ml-2 font-mono text-[10px] text-muted-foreground/60">
                        {perm.key}
                      </span>
                    </td>
                    {ROLES.map((role) => {
                      const granted = isGranted(role, perm.key)
                      return (
                        <td key={role} className="px-3 py-2.5 text-center">
                          {data ? (
                            granted ? (
                              <Check
                                className="mx-auto h-4 w-4 text-primary"
                                aria-label="Granted"
                              />
                            ) : (
                              <X
                                className="mx-auto h-4 w-4 text-muted-foreground/40"
                                aria-label="Not granted"
                              />
                            )
                          ) : (
                            <Loader2 className="mx-auto h-3 w-3 animate-spin text-muted-foreground/40" />
                          )}
                        </td>
                      )
                    })}
                  </tr>
                ))}
              </>
            ))}
          </tbody>
        </table>
      </div>

      {/* Pro custom roles gate */}
      {isPro ? (
        <div className="flex items-center justify-between pt-4 border-t border-border/50">
          <div>
            <p className="text-sm font-medium">Custom roles</p>
            <p className="text-xs text-muted-foreground mt-0.5">
              Create a role that copies from a preset and customize its permissions.
            </p>
          </div>
          <Button size="sm" variant="outline" disabled>
            <Plus className="h-4 w-4 mr-1.5" />
            Add custom role
          </Button>
        </div>
      ) : (
        <div className="flex items-center justify-between pt-4 border-t border-border/50">
          <p className="text-sm text-muted-foreground">
            Custom roles are available on Pro and above.
          </p>
          <Button size="sm" variant="outline" asChild>
            <Link href="/settings/billing">Upgrade to Pro</Link>
          </Button>
        </div>
      )}

      {/* Reset confirmation */}
      <AlertDialog
        open={!!resetTarget}
        onOpenChange={(open) => { if (!open) setResetTarget(null) }}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>
              Reset {resetTarget ? ROLE_LABEL[resetTarget] : ''} to defaults?
            </AlertDialogTitle>
            <AlertDialogDescription>
              This will restore all permissions to the InkOS-defined preset for this role.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => resetTarget && void handleReset(resetTarget)}
              disabled={resetting}
            >
              {resetting ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : null}
              Reset
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

