'use client'

import { useState } from 'react'
import { useForm, Controller } from 'react-hook-form'
import type { Resolver } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { useQuery, useMutation } from '@tanstack/react-query'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Button } from '@/components/ui/button'
import { Textarea } from '@/components/ui/textarea'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group'
import { queryKeys } from '@/lib/query-keys'
import { toast } from 'sonner'
import { cn } from '@/lib/utils'
import { Check, ChevronRight, Loader2 } from 'lucide-react'

interface Artist {
  id: string
  display_name: string
  avatar_url: string | null
}

const schema = z.object({
  // Step 1 — Engagement details
  start_date: z.string().min(1, 'Start date required'),
  end_date: z.string().min(1, 'End date required'),
  split_pct_studio: z.coerce.number().min(0).max(100).default(30),
  split_pct_artist: z.coerce.number().min(0).max(100).default(70),
  flat_fee_cents: z.coerce.number().min(0).optional().nullable(),
  agreement_notes: z.string().max(2000).optional().nullable(),

  // Step 2 — Artist details
  artist_id: z.string().uuid().optional().nullable(),
  artist_display_name: z.string().max(200).optional().nullable(),
  contact_email: z.string().email('Invalid email').optional().nullable().or(z.literal('')),
  contact_phone: z.string().max(50).optional().nullable(),

  // Step 3 — Access level
  show_on_booking_page: z.boolean().default(true),
}).refine(
  (d) => {
    if (!d.start_date || !d.end_date) return true
    return new Date(d.end_date) >= new Date(d.start_date)
  },
  { message: 'End date must be after start date', path: ['end_date'] }
).refine(
  (d) => (d.artist_id && d.artist_id.length > 0) || (d.artist_display_name && d.artist_display_name.length > 0),
  { message: 'Select an existing artist or enter a display name', path: ['artist_id'] }
)

type FormValues = z.infer<typeof schema>

interface CreateEngagementModalProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  onSuccess?: (id: string) => void
}

// Step indicator component
function StepIndicator({ current, total }: { current: number; total: number }) {
  const steps = [
    { label: 'Engagement', desc: 'Dates & split' },
    { label: 'Artist', desc: 'Who & contact' },
    { label: 'Access', desc: 'Booking visibility' },
  ]

  return (
    <div className="flex items-center gap-0 mb-6">
      {steps.map((step, i) => {
        const num = i + 1
        const done = num < current
        const active = num === current
        return (
          <div key={num} className="flex items-center flex-1 last:flex-none">
            <div className="flex flex-col items-center gap-1">
              <div
                className={cn(
                  'h-7 w-7 rounded-full flex items-center justify-center text-xs font-semibold transition-colors',
                  done && 'bg-primary text-primary-foreground',
                  active && 'bg-primary text-primary-foreground ring-2 ring-primary/30',
                  !done && !active && 'bg-muted text-muted-foreground',
                )}
              >
                {done ? <Check className="h-3.5 w-3.5" /> : num}
              </div>
              <span className={cn('text-[10px] font-medium', active ? 'text-foreground' : 'text-muted-foreground')}>
                {step.label}
              </span>
            </div>
            {i < total - 1 && (
              <div className={cn('flex-1 h-px mx-2 mb-4', num < current ? 'bg-primary' : 'bg-border')} />
            )}
          </div>
        )
      })}
    </div>
  )
}

export function CreateEngagementModal({ open, onOpenChange, onSuccess }: CreateEngagementModalProps) {
  const [step, setStep] = useState(1)

  const {
    register,
    control,
    handleSubmit,
    reset,
    watch,
    setValue,
    trigger,
    formState: { errors },
  } = useForm<FormValues>({
    resolver: zodResolver(schema) as Resolver<FormValues>,
    defaultValues: {
      artist_id: null,
      artist_display_name: null,
      start_date: '',
      end_date: '',
      split_pct_studio: 30,
      split_pct_artist: 70,
      flat_fee_cents: null,
      contact_email: null,
      contact_phone: null,
      agreement_notes: null,
      show_on_booking_page: true,
    },
  })

  const artistId = watch('artist_id')

  const { data: artistsData } = useQuery({
    queryKey: queryKeys.artists.list('studio'),
    queryFn: async () => {
      const res = await fetch('/api/artists')
      if (!res.ok) throw new Error('Failed to fetch artists')
      const json = await res.json() as { data: Artist[] }
      return json.data
    },
    enabled: open,
  })

  const handleStudioSplitChange = (value: string) => {
    const studio = parseFloat(value) || 0
    setValue('split_pct_studio', studio)
    setValue('split_pct_artist', Math.max(0, 100 - studio))
  }

  const mutation = useMutation({
    mutationFn: async (values: FormValues) => {
      const res = await fetch('/api/guest-artists/engagements', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...values,
          contact_email: values.contact_email === '' ? null : values.contact_email,
        }),
      })
      if (!res.ok) {
        const err = await res.json() as { error: unknown }
        throw new Error(typeof err.error === 'string' ? err.error : 'Failed to create engagement')
      }
      return res.json() as Promise<{ data: { id: string } }>
    },
    onSuccess: (result) => {
      toast.success('Guest engagement created')
      onOpenChange(false)
      reset()
      setStep(1)
      onSuccess?.(result.data.id)
    },
    onError: (err) => {
      toast.error(err instanceof Error ? err.message : 'Failed to create engagement')
    },
  })

  const handleClose = () => {
    onOpenChange(false)
    reset()
    setStep(1)
  }

  const goNext = async () => {
    let valid = false
    if (step === 1) {
      valid = await trigger(['start_date', 'end_date', 'split_pct_studio', 'split_pct_artist'])
    } else if (step === 2) {
      valid = await trigger(['artist_id', 'artist_display_name', 'contact_email'])
    }
    if (valid) setStep((s) => s + 1)
  }

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-lg max-h-[90vh] flex flex-col">
        <DialogHeader>
          <DialogTitle>Create Guest Engagement</DialogTitle>
          <DialogDescription>
            Set up a visiting artist engagement in 3 steps
          </DialogDescription>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto -mx-6 px-6">
          <div className="py-4">
            <StepIndicator current={step} total={3} />

            {/* Step 1 — Engagement Details */}
            {step === 1 && (
              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-3">
                  <div className="space-y-1">
                    <Label htmlFor="engagement-start">Start Date <span className="text-destructive">*</span></Label>
                    <Input id="engagement-start" type="date" {...register('start_date')} />
                    {errors.start_date && <p className="text-xs text-destructive">{errors.start_date.message}</p>}
                  </div>
                  <div className="space-y-1">
                    <Label htmlFor="engagement-end">End Date <span className="text-destructive">*</span></Label>
                    <Input id="engagement-end" type="date" {...register('end_date')} />
                    {errors.end_date && <p className="text-xs text-destructive">{errors.end_date.message}</p>}
                  </div>
                </div>

                <div className="space-y-2">
                  <p className="text-sm font-medium">Commission Split</p>
                  <div className="grid grid-cols-2 gap-3">
                    <div className="space-y-1">
                      <Label htmlFor="split-studio">Studio %</Label>
                      <Controller
                        control={control}
                        name="split_pct_studio"
                        render={({ field }) => (
                          <Input
                            id="split-studio"
                            type="number"
                            min="0"
                            max="100"
                            step="5"
                            value={field.value}
                            onChange={(e) => handleStudioSplitChange(e.target.value)}
                          />
                        )}
                      />
                      {errors.split_pct_studio && <p className="text-xs text-destructive">{errors.split_pct_studio.message}</p>}
                    </div>
                    <div className="space-y-1">
                      <Label htmlFor="split-artist">Artist %</Label>
                      <Input
                        id="split-artist"
                        type="number"
                        min="0"
                        max="100"
                        step="5"
                        readOnly
                        {...register('split_pct_artist', { valueAsNumber: true })}
                      />
                    </div>
                  </div>
                </div>

                <div className="space-y-1">
                  <Label htmlFor="engagement-fee">
                    Flat Fee ($) <span className="text-sm text-muted-foreground font-normal">(optional)</span>
                  </Label>
                  <Controller
                    control={control}
                    name="flat_fee_cents"
                    render={({ field }) => (
                      <Input
                        id="engagement-fee"
                        type="number"
                        step="0.01"
                        min="0"
                        placeholder="0.00"
                        value={field.value !== null && field.value !== undefined ? field.value / 100 : ''}
                        onChange={(e) =>
                          field.onChange(e.target.value === '' ? null : Math.round(parseFloat(e.target.value) * 100))
                        }
                      />
                    )}
                  />
                </div>

                <div className="space-y-1">
                  <Label htmlFor="engagement-notes">Agreement Notes <span className="text-sm text-muted-foreground font-normal">(optional)</span></Label>
                  <Textarea
                    id="engagement-notes"
                    rows={3}
                    placeholder="Studio provides: needles, ink. Artist brings own machine. Deposit required..."
                    {...register('agreement_notes')}
                  />
                </div>
              </div>
            )}

            {/* Step 2 — Artist Details */}
            {step === 2 && (
              <div className="space-y-4">
                <div className="space-y-1">
                  <Label htmlFor="engagement-artist">Existing Artist <span className="text-sm text-muted-foreground font-normal">(optional)</span></Label>
                  <Controller
                    control={control}
                    name="artist_id"
                    render={({ field }) => (
                      <Select
                        value={field.value ?? 'new'}
                        onValueChange={(v) => {
                          field.onChange(v === 'new' ? null : v)
                          if (v === 'new') setValue('artist_display_name', null)
                        }}
                      >
                        <SelectTrigger id="engagement-artist" className="w-full">
                          <SelectValue placeholder="Select artist or create new" />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="new">+ New guest artist</SelectItem>
                          {(artistsData ?? []).map((a) => (
                            <SelectItem key={a.id} value={a.id}>{a.display_name}</SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    )}
                  />
                  {errors.artist_id && <p className="text-xs text-destructive">{errors.artist_id.message}</p>}
                </div>

                {!artistId && (
                  <div className="space-y-1">
                    <Label htmlFor="engagement-name">
                      Guest Artist Name <span className="text-destructive">*</span>
                    </Label>
                    <Input
                      id="engagement-name"
                      placeholder="Jane Doe"
                      {...register('artist_display_name')}
                    />
                    {errors.artist_display_name && (
                      <p className="text-xs text-destructive">{errors.artist_display_name.message}</p>
                    )}
                  </div>
                )}

                <div className="grid grid-cols-2 gap-3">
                  <div className="space-y-1">
                    <Label htmlFor="engagement-email">Contact Email</Label>
                    <Input
                      id="engagement-email"
                      type="email"
                      placeholder="artist@email.com"
                      {...register('contact_email')}
                    />
                    {errors.contact_email && <p className="text-xs text-destructive">{errors.contact_email.message}</p>}
                  </div>
                  <div className="space-y-1">
                    <Label htmlFor="engagement-phone">Contact Phone</Label>
                    <Input
                      id="engagement-phone"
                      placeholder="+1 555-555-5555"
                      {...register('contact_phone')}
                    />
                  </div>
                </div>
              </div>
            )}

            {/* Step 3 — Access Level */}
            {step === 3 && (
              <div className="space-y-4">
                <p className="text-sm text-muted-foreground">
                  Control how this guest artist appears to clients booking online.
                </p>

                <Controller
                  control={control}
                  name="show_on_booking_page"
                  render={({ field }) => (
                    <RadioGroup
                      value={field.value ? 'visible' : 'hidden'}
                      onValueChange={(v) => field.onChange(v === 'visible')}
                      className="space-y-2"
                    >
                      {[
                        {
                          value: 'visible',
                          label: 'Visible on booking page',
                          desc: 'Clients can see and book with this artist directly.',
                        },
                        {
                          value: 'hidden',
                          label: 'Hidden from booking page',
                          desc: 'Only studio staff can assign bookings to this artist.',
                        },
                      ].map((opt) => (
                        <label
                          key={opt.value}
                          className={cn(
                            'flex items-start gap-3 p-3 rounded-lg border cursor-pointer transition-colors duration-150',
                            field.value === (opt.value === 'visible')
                              ? 'border-primary/50 bg-primary/[0.06]'
                              : 'border-border/50 hover:border-border',
                          )}
                        >
                          <RadioGroupItem value={opt.value} className="mt-0.5" />
                          <div>
                            <p className="text-sm font-semibold">{opt.label}</p>
                            <p className="text-xs text-muted-foreground mt-0.5">{opt.desc}</p>
                          </div>
                        </label>
                      ))}
                    </RadioGroup>
                  )}
                />

                <div className="rounded-lg border border-border/40 bg-muted/20 p-3 text-xs text-muted-foreground">
                  You can change booking page visibility at any time from the engagement settings.
                </div>
              </div>
            )}
          </div>
        </div>

        <DialogFooter className="pt-4 border-t border-border">
          {step > 1 && (
            <Button variant="ghost" onClick={() => setStep((s) => s - 1)} className="mr-auto">
              Back
            </Button>
          )}
          <Button variant="outline" onClick={handleClose}>
            Cancel
          </Button>
          {step < 3 ? (
            <Button onClick={() => void goNext()}>
              Next
              <ChevronRight className="ml-1.5 h-4 w-4" />
            </Button>
          ) : (
            <Button
              onClick={handleSubmit((v) => mutation.mutate(v))}
              disabled={mutation.isPending}
            >
              {mutation.isPending ? (
                <><Loader2 className="mr-2 h-4 w-4 animate-spin" />Creating…</>
              ) : (
                'Create Engagement'
              )}
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { Button } from '@/components/ui/button'
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group'
import { Label } from '@/components/ui/label'
import { Skeleton } from '@/components/ui/skeleton'
import { EngagementDetailView } from '@/components/guest-artists/EngagementDetailView'
import { queryKeys } from '@/lib/query-keys'
import { toast } from 'sonner'
import { cn } from '@/lib/utils'
import {
  CalendarDays,
  Eye,
  EyeOff,
  Shield,
  Loader2,
  Info,
} from 'lucide-react'

interface GuestEngagementTabsProps {
  id: string
  isOwner: boolean
}

// ── Access Tab ────────────────────────────────────────────────────────────────

interface GuestArtistAccessData {
  show_on_booking_page: boolean
  can_view_client_history: boolean
  can_view_other_bookings: boolean
  can_send_messages: boolean
}

const ACCESS_OPTIONS: {
  key: keyof Omit<GuestArtistAccessData, 'show_on_booking_page'>
  label: string
  description: string
  icon: React.ComponentType<{ className?: string }>
}[] = [
  {
    key: 'can_view_client_history',
    label: 'View client history',
    description: 'See previous appointments and notes for their own clients.',
    icon: Eye,
  },
  {
    key: 'can_view_other_bookings',
    label: 'View other bookings',
    description: 'See the full studio calendar including other artists' appointments.',
    icon: CalendarDays,
  },
  {
    key: 'can_send_messages',
    label: 'Send messages',
    description: 'Message clients directly from the InkOS app.',
    icon: Shield,
  },
]

function AccessPermissionToggle({
  label,
  description,
  icon: Icon,
  enabled,
  onChange,
  disabled,
}: {
  label: string
  description: string
  icon: React.ComponentType<{ className?: string }>
  enabled: boolean
  onChange: (v: boolean) => void
  disabled: boolean
}) {
  return (
    <div className="flex items-start justify-between gap-4 py-3 border-b border-border/40 last:border-0">
      <div className="flex items-start gap-3">
        <div className="h-8 w-8 rounded-lg bg-muted/50 flex items-center justify-center shrink-0 mt-0.5">
          <Icon className="h-4 w-4 text-muted-foreground" />
        </div>
        <div>
          <p className="text-sm font-medium">{label}</p>
          <p className="text-xs text-muted-foreground mt-0.5">{description}</p>
        </div>
      </div>
      <button
        type="button"
        role="switch"
        aria-checked={enabled}
        disabled={disabled}
        onClick={() => onChange(!enabled)}
        className={cn(
          'relative inline-flex h-5 w-9 shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50',
          enabled ? 'bg-primary' : 'bg-input',
        )}
      >
        <span
          className={cn(
            'pointer-events-none block h-4 w-4 rounded-full bg-background shadow-[var(--shadow-soft)] ring-0 transition-transform duration-200',
            enabled ? 'translate-x-4' : 'translate-x-0',
          )}
        />
      </button>
    </div>
  )
}

function AccessTab({ id, isOwner }: { id: string; isOwner: boolean }) {
  const queryClient = useQueryClient()

  const { data, isLoading } = useQuery({
    queryKey: [...queryKeys.guestArtists.engagement(id), 'access'],
    queryFn: async () => {
      const res = await fetch(`/api/guest-artists/${id}/access`)
      if (!res.ok) throw new Error('Failed to fetch access settings')
      const json = await res.json() as { data: GuestArtistAccessData }
      return json.data
    },
  })

  const mutation = useMutation({
    mutationFn: async (patch: Partial<GuestArtistAccessData>) => {
      const res = await fetch(`/api/guest-artists/${id}/access`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(patch),
      })
      if (!res.ok) throw new Error('Failed to update access')
      return res.json() as Promise<{ data: GuestArtistAccessData }>
    },
    onSuccess: (result) => {
      void queryClient.setQueryData(
        [...queryKeys.guestArtists.engagement(id), 'access'],
        result.data,
      )
      toast.success('Access settings updated')
    },
    onError: () => toast.error('Failed to update access settings'),
  })

  if (isLoading) {
    return (
      <div className="space-y-4 py-4">
        {Array.from({ length: 4 }).map((_, i) => (
          <Skeleton key={i} className="h-14 w-full rounded-lg" />
        ))}
      </div>
    )
  }

  if (!data) {
    return (
      <div className="py-8 text-center text-sm text-muted-foreground">
        Failed to load access settings.
      </div>
    )
  }

  return (
    <div className="space-y-6 py-4">
      {/* Booking page visibility */}
      <div className="rounded-xl border border-border bg-card p-5 space-y-3">
        <div className="flex items-center gap-2">
          <Eye className="h-4 w-4 text-muted-foreground" />
          <p className="text-sm font-semibold">Booking Page Visibility</p>
        </div>
        <p className="text-xs text-muted-foreground">
          Control whether clients can see and book with this artist from the public booking page.
        </p>
        <RadioGroup
          value={data.show_on_booking_page ? 'visible' : 'hidden'}
          onValueChange={(v) => {
            if (!isOwner) return
            mutation.mutate({ show_on_booking_page: v === 'visible' })
          }}
          className="space-y-2"
        >
          {[
            { value: 'visible', label: 'Visible', icon: Eye, desc: 'Clients can book this artist online.' },
            { value: 'hidden', label: 'Hidden', icon: EyeOff, desc: 'Staff-only — not visible to clients.' },
          ].map((opt) => {
            const Icon = opt.icon
            const selected = data.show_on_booking_page === (opt.value === 'visible')
            return (
              <label
                key={opt.value}
                className={cn(
                  'flex items-start gap-3 p-3 rounded-lg border cursor-pointer transition-colors duration-150',
                  !isOwner && 'cursor-default opacity-70',
                  selected ? 'border-primary/50 bg-primary/[0.06]' : 'border-border/50',
                  isOwner && !selected && 'hover:border-border',
                )}
              >
                <RadioGroupItem value={opt.value} className="mt-0.5" disabled={!isOwner} />
                <div className="flex items-center gap-2">
                  <Icon className="h-4 w-4 text-muted-foreground" />
                  <div>
                    <p className="text-sm font-medium">{opt.label}</p>
                    <p className="text-xs text-muted-foreground">{opt.desc}</p>
                  </div>
                </div>
              </label>
            )
          })}
        </RadioGroup>
      </div>

      {/* Granular permissions */}
      <div className="rounded-xl border border-border bg-card p-5 space-y-1">
        <div className="flex items-center gap-2 mb-3">
          <Shield className="h-4 w-4 text-muted-foreground" />
          <p className="text-sm font-semibold">App Permissions</p>
        </div>
        {ACCESS_OPTIONS.map((opt) => (
          <AccessPermissionToggle
            key={opt.key}
            label={opt.label}
            description={opt.description}
            icon={opt.icon}
            enabled={data[opt.key]}
            onChange={(v) => {
              if (!isOwner) return
              mutation.mutate({ [opt.key]: v })
            }}
            disabled={!isOwner || mutation.isPending}
          />
        ))}
      </div>

      {!isOwner && (
        <div className="flex items-start gap-2 rounded-lg bg-muted/30 px-3 py-2.5 text-xs text-muted-foreground">
          <Info className="h-3.5 w-3.5 mt-0.5 shrink-0" />
          Only studio owners can change access settings for guest artists.
        </div>
      )}

      {isOwner && mutation.isPending && (
        <div className="flex items-center gap-2 text-xs text-muted-foreground">
          <Loader2 className="h-3 w-3 animate-spin" />
          Saving…
        </div>
      )}
    </div>
  )
}

// ── Schedule Tab ──────────────────────────────────────────────────────────────

function ScheduleTab({ id }: { id: string }) {
  return (
    <div className="py-6 space-y-4">
      <p className="text-sm text-muted-foreground">
        View this guest artist&apos;s schedule for their engagement period. Schedule editing is
