import type { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import { z } from 'zod'

const PatchAccessSchema = z.object({
  show_on_booking_page: z.boolean().optional(),
  // Future: add can_view_client_history, can_view_other_bookings, can_send_messages
  // after migration adds those columns to guest_artist_engagements
})

export async function GET(
  _req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const supabase = await createClient()

  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('role, studio_id')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return Response.json({ error: 'No membership' }, { status: 403 })

  const { data: engagement, error } = await supabase
    .from('guest_artist_engagements')
    .select('show_on_booking_page')
    .eq('id', id)
    .eq('studio_id', member.studio_id)
    .single()

  if (error || !engagement) {
    logger.warn({ engagementId: id, error }, 'guest_artist_access GET: engagement not found')
    return Response.json({ error: 'Not found' }, { status: 404 })
  }

  // Stub permissions not yet in DB — will be migrated in sprint 9
  return Response.json({
    data: {
      show_on_booking_page: engagement.show_on_booking_page,
      can_view_client_history: false,
      can_view_other_bookings: false,
      can_send_messages: false,
    },
  })
}

export async function PATCH(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params

  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'Rate limited' }, { status: 429 })

  const supabase = await createClient()

  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('role, studio_id')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return Response.json({ error: 'No membership' }, { status: 403 })

  if (member.role !== 'owner' && member.role !== 'admin') {
    return Response.json({ error: 'Forbidden — only owners and admins can change access' }, { status: 403 })
  }

  let body: unknown
  try {
    body = await req.json()
  } catch {
    return Response.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = PatchAccessSchema.safeParse(body)
  if (!parsed.success) {
    return Response.json({ error: parsed.error.flatten() }, { status: 422 })
  }

  const patch = parsed.data

  // Only update columns that exist in the DB right now
  const dbPatch: Record<string, unknown> = {}
  if (patch.show_on_booking_page !== undefined) {
    dbPatch['show_on_booking_page'] = patch.show_on_booking_page
  }

  if (Object.keys(dbPatch).length === 0) {
    // Nothing to update — return current state
    const { data: current } = await supabase
      .from('guest_artist_engagements')
      .select('show_on_booking_page')
      .eq('id', id)
      .eq('studio_id', member.studio_id)
      .single()

    return Response.json({
      data: {
        show_on_booking_page: current?.show_on_booking_page ?? false,
        can_view_client_history: false,
        can_view_other_bookings: false,
        can_send_messages: false,
      },
    })
  }

  const { data: updated, error } = await supabase
    .from('guest_artist_engagements')
    .update(dbPatch)
    .eq('id', id)
    .eq('studio_id', member.studio_id)
    .select('show_on_booking_page')
    .single()

  if (error || !updated) {
    logger.error({ engagementId: id, error }, 'guest_artist_access PATCH: update failed')
    return Response.json({ error: 'Update failed' }, { status: 500 })
  }

  return Response.json({
    data: {
      show_on_booking_page: updated.show_on_booking_page,
      can_view_client_history: false,
      can_view_other_bookings: false,
      can_send_messages: false,
    },
  })
}

import type { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'
import { z } from 'zod'

const QuerySchema = z.object({
  from: z.string().regex(/^\d{4}-\d{2}-\d{2}$/).optional(),
  to: z.string().regex(/^\d{4}-\d{2}-\d{2}$/).optional(),
  count_only: z.enum(['true', 'false']).optional().transform((v) => v === 'true'),
})

export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const supabase = await createClient()

  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return Response.json({ error: 'No membership' }, { status: 403 })

  const url = new URL(req.url)
  const raw = {
    from: url.searchParams.get('from') ?? undefined,
    to: url.searchParams.get('to') ?? undefined,
    count_only: url.searchParams.get('count_only') ?? undefined,
  }

  const parsed = QuerySchema.safeParse(raw)
  if (!parsed.success) {
    return Response.json({ error: parsed.error.flatten() }, { status: 422 })
  }

  const { from, to, count_only } = parsed.data

  // Verify artist belongs to the same studio
  const { data: artist } = await supabase
    .from('artists')
    .select('id')
    .eq('id', id)
    .eq('studio_id', member.studio_id)
    .single()

  if (!artist) return Response.json({ error: 'Artist not found' }, { status: 404 })

  try {
    let query = supabase
      .from('bookings')
      .select('id', { count: 'exact', head: count_only })
      .eq('artist_id', id)
      .eq('studio_id', member.studio_id)
      .not('status', 'in', '(cancelled,no_show)')

    if (from) {
      query = query.gte('scheduled_at', `${from}T00:00:00.000Z`)
    }
    if (to) {
      query = query.lte('scheduled_at', `${to}T23:59:59.999Z`)
    }

    const { count, data, error } = await query

    if (error) {
      logger.error({ artistId: id, error }, 'artist bookings GET: query failed')
      return Response.json({ error: 'Query failed' }, { status: 500 })
    }

    if (count_only) {
      return Response.json({ count: count ?? 0 })
    }

    return Response.json({ data: data ?? [], count: count ?? 0 })
  } catch (err) {
    logger.error({ artistId: id, err }, 'artist bookings GET: unexpected error')
    return Response.json({ error: 'Server error' }, { status: 500 })
  }
}

/**
 * GET /api/schedule/week?from=YYYY-MM-DD&to=YYYY-MM-DD&artist_ids[]=...
 *
 * Returns schedule slots for all (or filtered) studio artists in a date range.
 * Uses day_of_week + effective_from/effective_until to resolve active slots.
 */
import type { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'
import { z } from 'zod'

const QuerySchema = z.object({
  from: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
  to: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
})

export async function GET(req: NextRequest) {
  const supabase = await createClient()

  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return Response.json({ error: 'No membership' }, { status: 403 })

  const url = new URL(req.url)
  const parsed = QuerySchema.safeParse({
    from: url.searchParams.get('from'),
    to: url.searchParams.get('to'),
  })
  if (!parsed.success) {
    return Response.json({ error: parsed.error.flatten() }, { status: 422 })
  }

  const { from, to } = parsed.data
  const artistIds = url.searchParams.getAll('artist_ids[]')

  try {
    let query = supabase
      .from('artist_schedules')
      .select('id, artist_id, day_of_week, start_time, end_time, effective_from, effective_until')
      .eq('studio_id', member.studio_id)
      .or(`effective_until.is.null,effective_until.gte.${from}`)

    if (artistIds.length > 0) {
      query = query.in('artist_id', artistIds)
    }

    if (from) {
      query = query.lte('effective_from', to)
    }

    const { data, error } = await query.order('start_time', { ascending: true })

    if (error) {
      logger.error({ error }, 'schedule/week GET: query failed')
      return Response.json({ error: 'Query failed' }, { status: 500 })
    }

    return Response.json({ data: data ?? [] })
  } catch (err) {
    logger.error({ err }, 'schedule/week GET: unexpected error')
    return Response.json({ error: 'Server error' }, { status: 500 })
  }
}

