/**
 * POST /api/schedule/copy-week
 *
 * Copies all schedule slots from {source_week_start} to {target_week_start}.
 * Adjusts day_of_week mapping, preserves start_time/end_time.
 * Does NOT copy time-off blocks (those are separate artist-level requests).
 */
import type { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import { z } from 'zod'

const CopyWeekSchema = z.object({
  source_week_start: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
  target_week_start: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
  artist_ids: z.array(z.string().uuid()).optional(),
})

export async function POST(req: NextRequest) {
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'Rate limited' }, { status: 429 })

  const supabase = await createClient()

  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('role, studio_id')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return Response.json({ error: 'No membership' }, { status: 403 })

  if (member.role !== 'owner' && member.role !== 'admin') {
    return Response.json({ error: 'Forbidden' }, { status: 403 })
  }

  let body: unknown
  try {
    body = await req.json()
  } catch {
    return Response.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = CopyWeekSchema.safeParse(body)
  if (!parsed.success) {
    return Response.json({ error: parsed.error.flatten() }, { status: 422 })
  }

  const { source_week_start, target_week_start, artist_ids } = parsed.data

  try {
    // Fetch source slots effective during source week
    let sourceQuery = supabase
      .from('artist_schedules')
      .select('artist_id, day_of_week, start_time, end_time')
      .eq('studio_id', member.studio_id)
      .lte('effective_from', source_week_start)
      .or(`effective_until.is.null,effective_until.gte.${source_week_start}`)

    if (artist_ids && artist_ids.length > 0) {
      sourceQuery = sourceQuery.in('artist_id', artist_ids)
    }

    const { data: sourceSlots, error: fetchError } = await sourceQuery

    if (fetchError) {
      logger.error({ error: fetchError }, 'copy-week: fetch source failed')
      return Response.json({ error: 'Failed to fetch source slots' }, { status: 500 })
    }

    if (!sourceSlots || sourceSlots.length === 0) {
      return Response.json({ data: { copied: 0 } })
    }

    const newSlots = sourceSlots.map((slot) => ({
      studio_id: member.studio_id,
      artist_id: slot.artist_id,
      day_of_week: slot.day_of_week,
      start_time: slot.start_time,
      end_time: slot.end_time,
      effective_from: target_week_start,
      effective_until: null,
    }))

    const { error: insertError } = await supabase
      .from('artist_schedules')
      .insert(newSlots)

    if (insertError) {
      logger.error({ error: insertError }, 'copy-week: insert failed')
      return Response.json({ error: 'Failed to copy slots' }, { status: 500 })
    }

    return Response.json({ data: { copied: newSlots.length } })
  } catch (err) {
    logger.error({ err }, 'copy-week: unexpected error')
    return Response.json({ error: 'Server error' }, { status: 500 })
  }
}

