  'mon-fri-9to5': [1, 2, 3, 4, 5].map((d) => ({ day_of_week: d, start_time: '09:00:00', end_time: '17:00:00' })),
  'mon-sat-10to6': [1, 2, 3, 4, 5, 6].map((d) => ({ day_of_week: d, start_time: '10:00:00', end_time: '18:00:00' })),
  'weekend-only': [0, 6].map((d) => ({ day_of_week: d, start_time: '10:00:00', end_time: '16:00:00' })),
