  } catch {
    return Response.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = ApplyTemplateSchema.safeParse(body)
  if (!parsed.success) {
    return Response.json({ error: parsed.error.flatten() }, { status: 422 })
  }

  const { template_id, target_week_start, artist_ids } = parsed.data

  // Resolve template slots
  let templateSlots: { day_of_week: number; start_time: string; end_time: string }[]

  if (BUILTIN_TEMPLATES[template_id]) {
    templateSlots = BUILTIN_TEMPLATES[template_id]!
  } else {
    // TODO: look up from schedule_templates table once migration runs
    return Response.json(
      { error: 'Custom templates not yet available — run Sprint 8 DB migration' },
      { status: 501 },
    )
  }

  try {
    const newSlots = artist_ids.flatMap((artistId) =>
      templateSlots.map((slot) => ({
        studio_id: member.studio_id,
        artist_id: artistId,
        day_of_week: slot.day_of_week,
        start_time: slot.start_time,
        end_time: slot.end_time,
        effective_from: target_week_start,
        effective_until: null,
      })),
    )

    const { error: insertError } = await supabase
      .from('artist_schedules')
      .insert(newSlots)

    if (insertError) {
      logger.error({ error: insertError }, 'apply-template: insert failed')
      return Response.json({ error: 'Failed to apply template' }, { status: 500 })
    }

    return Response.json({ data: { applied: newSlots.length } })
  } catch (err) {
    logger.error({ err }, 'apply-template: unexpected error')
    return Response.json({ error: 'Server error' }, { status: 500 })
  }
}

